WITH with_latest AS (SELECT s.*, top1.web_event_duration_sec FROM sessions s LEFT JOIN LATERAL (SELECT c.duration_sec AS web_event_duration_sec FROM web_events c WHERE c.session_id = s.id ORDER BY c.duration_sec DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT browser, DATE_TRUNC('YEAR', started_at) AS year_start, CASE WHEN web_event_duration_sec >= 491 THEN 'PREMIUM' ELSE 'STANDARD' END AS web_event_duration_sec_tier, MAX(started_at) AS last_started_at, MAX(started_at) AS last_seen, APPROX_PERCENTILE(web_event_duration_sec, 0.95) AS web_event_duration_sec_p95, SORT_ARRAY(COLLECT_SET(browser)) AS browser_list, MAX(web_event_duration_sec) FILTER (WHERE browser = 'Edge') AS edge_max_web_event_duration_sec, GROUPING(browser) AS grouping_id FROM with_latest GROUP BY GROUPING SETS ((browser, DATE_TRUNC('YEAR', started_at), CASE WHEN web_event_duration_sec >= 491 THEN 'PREMIUM' ELSE 'STANDARD' END), (browser, DATE_TRUNC('YEAR', started_at))) ORDER BY year_start ASC NULLS FIRST;
